/** 亿元 → 元。mock 里金额一律用元，只有 circulation 按契约用亿元。 */
function lhbYuan(yi: number): number {
  return Math.round(yi * 100_000_000);
}

function lhbRound(n: number, digits: number): number {
  const base = 10 ** digits;
  return Math.round(n * base) / base;
}

function lhbStamp(): number {
  return Math.floor(Date.now() / 1000);
}

function lhbStock(code: string): Stock | undefined {
  return mockDay.stocks.find((stock) => stock.code === code);
}

/** mockKlines.day 最近 count 个交易日，YYYYMMDD，新 → 旧。 */
function lhbTradingDays(count: number): string[] {
  return mockKlines.day.candles
    .slice(-count)
    .map((candle) => candle.date.replace(/-/g, ""))
    .reverse();
}

