function buildLhbBoardRows(): LhbStock[] {
  const rows: LhbStock[] = LHB_BOARD_SEEDS.map((seed) => {
    const stock = lhbStock(seed.code);
    const floatCapYi = Math.min(900, Math.max(20, lhbRound((stock?.floatCap ?? 6_000_000_000) / 100_000_000, 1)));
    const floatCap = lhbYuan(floatCapYi);
    return {
      code: seed.code,
      name: stock?.name ?? seed.code,
      pct: seed.pct,
      netBuy: lhbYuan(seed.net),
      seats: seed.seats,
      turnover: lhbYuan(seed.turnover),
      turnoverRate: seed.turnoverRate,
      floatCap,
      marketCap: Math.round(floatCap * 1.3),
      board: seed.board,
      sector: stock?.primarySector || stock?.sectors[0] || "未归类",
    };
  });
  return rows.sort((a, b) => b.netBuy - a.netBuy);
}

const LHB_BOARD_ROWS: LhbStock[] = buildLhbBoardRows();

