const LHB_SEATS: LhbAgency[] = LHB_AGENCY_SEEDS.map((seed, index) => {
  const buy = lhbYuan(seed.buy);
  const sell = lhbYuan(seed.sell);
  return {
    id: `yyz-${String(index + 1).padStart(3, "0")}`,
    name: seed.name,
    buy,
    sell,
    net: buy - sell,
    joinCount: seed.joinCount,
    tags: [...seed.tags],
  };
});

const LHB_AGENCY_ROWS: LhbAgency[] = [...LHB_SEATS].sort((a, b) => b.net - a.net);

/** 按名号聚合席位榜：同一席位命中多个名号时分别计入。 */
function buildLhbHot(rows: LhbAgency[]): LhbHotMoneyTag[] {
  const buckets = new Map<string, LhbHotMoneyTag>();
  for (const row of rows) {
    for (const tag of row.tags) {
      if (tag === "机构专用") continue;
      const bucket = buckets.get(tag) ?? { tag, buy: 0, sell: 0, net: 0, seats: [] };
      bucket.buy += row.buy;
      bucket.sell += row.sell;
      bucket.net = bucket.buy - bucket.sell;
      bucket.seats.push({ id: row.id, name: row.name, buy: row.buy, sell: row.sell, net: row.net });
      buckets.set(tag, bucket);
    }
  }
  return [...buckets.values()]
    .map((bucket) => ({ ...bucket, seats: [...bucket.seats].sort((a, b) => b.net - a.net) }))
    .sort((a, b) => b.net - a.net);
}

const LHB_HOT: LhbHotMoneyTag[] = buildLhbHot(LHB_AGENCY_ROWS);

