/* —— 个股明细：1-2 个上榜理由 block，每 block 5 买 + 5 卖席位 —— */

const LHB_BUY_WEIGHTS = [0.28, 0.23, 0.19, 0.16, 0.14];
const LHB_SELL_WEIGHTS = [0.27, 0.22, 0.19, 0.17, 0.15];

/** 两个 block 各取 5 买 / 5 卖，下标指向 LHB_SEATS（营业部名与席位榜同一批）。 */
const LHB_DETAIL_SLOTS: Array<{ buy: number[]; sell: number[] }> = [
  { buy: [2, 3, 0, 8, 5], sell: [6, 7, 1, 4, 9] },
  { buy: [10, 12, 14, 16, 18], sell: [11, 13, 15, 17, 21] },
];

/** 少量席位补通用名号，让 tags 落在 2-3 个。 */
const LHB_DETAIL_EXTRA_TAGS: string[][] = [
  [],
  [],
  [],
  [],
  [],
  [],
  [],
  [],
  [],
  [],
  [],
  [],
  [],
  [],
  [],
  [],
  [],
  [],
  [],
  [],
];

const LHB_REASONS: Record<"up" | "down", string[][]> = {
  up: [
    ["日涨幅偏离值达7%", "日换手率达20%"],
    ["连续三个交易日内收盘价格涨幅偏离值累计达30%"],
  ],
  down: [
    ["有价格涨跌幅限制的日收盘价格跌幅偏离值达到7%"],
    ["连续三个交易日内收盘价格跌幅偏离值累计达20%"],
  ],
};

/** 金额按权重拆分，前 n-1 份取整到万元，最后一份兜剩余，保证合计精确。 */
function lhbSplit(total: number, weights: number[]): number[] {
  const step = 10_000;
  const parts: number[] = [];
  let used = 0;
  for (let i = 0; i < weights.length - 1; i += 1) {
    const part = Math.max(step, Math.round((total * weights[i]) / step) * step);
    parts.push(part);
    used += part;
  }
  parts.push(total - used);
  return parts;
}

function lhbSeatLevel(tags: string[]): number {
  if (tags.some((tag) => tag === "章盟主" || tag === "方新侠" || tag === "炒股养家")) return 3;
  if (tags.some((tag) => tag === "作手新一" || tag === "超级资金" || tag === "量化打板")) return 2;
  if (tags.some((tag) => tag === "一线游资" || tag === "赵老哥" || tag === "拉萨天团" || tag === "古北路")) return 1;
  return 0;
}

function lhbDetailSeat(seatIndex: number, slot: number, buy: number, sell: number): LhbSeat {
  const seat = LHB_SEATS[seatIndex];
  const tags = Array.from(new Set([...seat.tags, ...(LHB_DETAIL_EXTRA_TAGS[slot] ?? [])]));
  return {
    id: seat.id,
    name: seat.name,
    buy,
    sell,
    net: buy - sell,
    tags,
    level: lhbSeatLevel(tags),
    assoc: slot % 7 === 3,
    ydayBuy: slot % 5 === 1 ? (slot % 4) + 1 : 0,
    ydaySell: slot % 6 === 4 ? (slot % 3) + 1 : 0,
  };
}

export function buildLhbDetail(code: string, date: string): LhbDetail {
  const fallback = LHB_BOARD_ROWS[0];
  const stock = lhbStock(code) ?? lhbStock(fallback.code);
  const row = LHB_BOARD_ROWS.find((item) => item.code === (stock?.code ?? "")) ?? fallback;
  const reasonSets = row.pct >= 0 ? LHB_REASONS.up : LHB_REASONS.down;
  const blockCount = (row.code.charCodeAt(0) + row.code.charCodeAt(row.code.length - 1)) % 3 === 0 ? 2 : 1;
  const totalNet = row.netBuy;
  const firstNet = blockCount === 2 ? Math.round(totalNet * 0.62) : totalNet;
  const nets = blockCount === 2 ? [firstNet, totalNet - firstNet] : [totalNet];
  const days = lhbTradingDays(8);
  const onTimeCount = 5 + ((row.code.charCodeAt(1) + row.code.charCodeAt(2)) % 4);

  const blocks: LhbReasonBlock[] = nets.map((net, blockIndex) => {
    const gross = Math.max(Math.abs(net) * 2.2, 120_000_000);
    const buyTotal = Math.round((gross + net) / 2 / 10_000) * 10_000;
    const sellTotal = buyTotal - net;
    const buyAmounts = lhbSplit(buyTotal, LHB_BUY_WEIGHTS);
    const sellAmounts = lhbSplit(sellTotal, LHB_SELL_WEIGHTS);
    const slots = LHB_DETAIL_SLOTS[blockIndex] ?? LHB_DETAIL_SLOTS[0];
    const buy = slots.buy.map((seatIndex, i) => lhbDetailSeat(seatIndex, blockIndex * 10 + i, buyAmounts[i], 0));
    const sell = slots.sell.map((seatIndex, i) => lhbDetailSeat(seatIndex, blockIndex * 10 + 5 + i, 0, sellAmounts[i]));
    return {
      reasons: reasonSets[blockIndex] ?? reasonSets[0],
      buyTotal,
      sellTotal,
      buy,
      sell,
    };
  });

  return {
    code: row.code,
    name: row.name,
    date,
    pct: row.pct,
    turnoverRate: row.turnoverRate,
    circulation: lhbRound(row.floatCap / 100_000_000, 1),
    netBuy: totalNet,
    seatCount: blocks.reduce((sum, block) => sum + block.buy.length + block.sell.length, 0),
    onTime: days.slice(0, onTimeCount),
    blocks,
    source: "network",
    fetchedAt: lhbStamp(),
    warning: null,
  };
}

/* —— 5 个 command 的 payload builder —— */

export function buildLhbBoard(date: string): LhbBoard {
  return {
    requestedDate: date,
    date,
    fallback: false,
    rows: LHB_BOARD_ROWS.map((row) => ({ ...row })),
    source: "network",
    fetchedAt: lhbStamp(),
    warning: null,
  };
}

export function buildLhbAgencies(date: string): LhbAgencies {
  return {
    date,
    rows: LHB_AGENCY_ROWS.map((row) => ({ ...row, tags: [...row.tags] })),
    hot: LHB_HOT.map((tag) => ({ ...tag, seats: tag.seats.map((seat) => ({ ...seat })) })),
    source: "network",
    fetchedAt: lhbStamp(),
    warning: null,
  };
}

export function buildLhbInstitutions(date: string): LhbInstitutions {
  return {
    date,
    rows: LHB_INSTITUTION_ROWS.map((row) => ({ ...row })),
    source: "network",
    fetchedAt: lhbStamp(),
    warning: null,
  };
}

export function buildLhbSeatLog(seatId: string, days: number): LhbSeatLog {
  return {
    seatId,
    rows: LHB_SEAT_LOG_ROWS.map((row) => ({ ...row })),
    days,
    total: LHB_SEAT_LOG_ROWS.length,
    truncated: false,
    source: "network",
    fetchedAt: lhbStamp(),
    warning: null,
  };
}

